sp_widget.client_script:
api.controller = function($scope,$window,$location,$timeout) {
  var c = this;

  c.filteredQuotas = [];
  c.uiFilter       = { period: '', frequency: '', search: '' };

  /* ================= CREATE QUOTA ================= */
  /*
   * CHANGE: Store the current page URL in sessionStorage before navigating
   * to the Quota Builder. The Quota Builder back button reads this value
   * and returns to exactly this page — so the user lands back on
   * Quota Setup, not on the Administration main page.
   */
  c.createQuota = function() {
    /*
     * Store the current page URL in sessionStorage.
     * The Quota Builder back button reads this and returns here exactly.
     * We append ?returnTo=1 as a marker so the page knows it's a return.
     */
    var currentUrl = $location.absUrl();
    sessionStorage.setItem('qb_origin', currentUrl);

    $location.url('?id=quota_builder');
  };

	c.goBack = function() {
			$location.url('?id=incentnow_admin');
	};

  /* ================= VIEW ASSIGNMENTS ================= */
  /* No change — exact provided code */
  c.viewAssign = function() {
    $location.url('?id=quota_assignments');
  };

  /* ================= QUOTA SUMMARY ================= */
  c.getQuotaSummary = function() {
		var total = 0;
		var totalValue = 0;
		if (c.data.quotaAssignments) {
			c.data.quotaAssignments.forEach(function(q) {
				if ((q.status || '').toLowerCase() === 'active') {  // ✅ FILTER
					total++;
					totalValue += parseFloat(q.targetValue) || 0;
				}
			});
		}
		return {
			total: total,
			totalValue: totalValue
		};
	};

  /* ================= UI FILTER ================= */
  c.applyUIFilter = function() {
    var list = angular.copy(c.data.quotaAssignments || []);

    if (c.uiFilter.period) {
      list = list.filter(function(q) {
        return q.periodName === c.uiFilter.period;
      });
    }

    if (c.uiFilter.frequency) {
      list = list.filter(function(q) {
        return q.distributionMethod === c.uiFilter.frequency;
      });
    }

    if (c.uiFilter.search) {
      var s = c.uiFilter.search.toLowerCase();
      list = list.filter(function(q) {
        return q.name && q.name.toLowerCase().indexOf(s) !== -1;
      });
    }

    c.filteredQuotas = list;
  };

  /* ================= SET TAB ================= */
  c.setTab = function(tab) {
    c.data.activeTab = tab;

    if (tab === 'lookups') {
      c.server.get({ action: 'load_lookups' }).then(function(response) {
        c.data.lookupTables = (response.data && response.data.lookupTables) || [];
      });
      return;
    }

    if (tab === 'settings') {
      return;
    }

    c.server.update({
      action:    'refresh_all',
      period:    c.selectedQuotaPeriod,
      unit:      c.selectedQuotaUnit,
      activeTab: tab
    }).then(function(response) {
      c.data.quotaAssignments = response.data.quotaAssignments;
      c.data.quotaSummary     = response.data.quotaSummary;
      c.filteredQuotas        = angular.copy(c.data.quotaAssignments || []);
    });
  };

  /* ================= INIT ================= */
  c.$onInit = function() {
    c.filteredQuotas = c.data.quotaAssignments || [];

    c.server.update({ action: 'refresh_all' }).then(function(response) {
      c.data.quotaAssignments = response.data.quotaAssignments;
      c.data.quotaSummary     = response.data.quotaSummary;
      c.filteredQuotas        = angular.copy(c.data.quotaAssignments || []);
    });
  };


	// Approval Flow Pagination
		c.approvalCurrentPage = 1;
		c.approvalPageSize = 5;

		c.getPaginatedApprovalFlow = function () {

				if (!c.approvalFlow)
						return [];

				var start = (c.approvalCurrentPage - 1) * c.approvalPageSize;
				var end = start + c.approvalPageSize;

				return c.approvalFlow.slice(start, end);
		};

		c.approvalTotalPages = function () {

				if (!c.approvalFlow || c.approvalFlow.length === 0)
						return 1;

				return Math.ceil(c.approvalFlow.length / c.approvalPageSize);
		};

		c.nextApprovalPage = function () {

				if (c.approvalCurrentPage < c.approvalTotalPages()) {
						c.approvalCurrentPage++;
				}
		};

		c.prevApprovalPage = function () {

				if (c.approvalCurrentPage > 1) {
						c.approvalCurrentPage--;
				}
		};

	//approval flow

		c.showApprovalFlow = false;
		c.approvalFlow = [];

		c.openApprovalFlow = function(quotaId) {

			c.server.get({
					action: "getApprovalFlow",
					quotaId: quotaId
			}).then(function(response) {

					c.approvalFlow = response.data.approvalFlow;
					c.approvalCurrentPage = 1;
					c.showApprovalFlow = true;

					$timeout(function () {

							var el = document.getElementById("approvalFlowSection");

							if (el) {
									el.scrollIntoView({
											behavior: "smooth",
											block: "start"
									});
							}

					}, 100);
			});
	};

		$scope.$on('showQuotaApprovalFlow', function(event, data) {

			c.server.get({
					action: 'getApprovalFlow',
					quotaId: data.quotaId
			}).then(function(response){

					c.approvalFlow = response.data.approvalFlow;
					c.approvalCurrentPage = 1;
					c.showApprovalFlow = true;

					$timeout(function () {

							var el = document.getElementById("approvalFlowSection");

							if (el) {
									el.scrollIntoView({
											behavior: "smooth",
											block: "start"
									});
							}

					}, 100);

			});

	});

};

sp_widget.css:
.headd {
	  font-size: 2.6rem;
    font-weight: 700;
    color: #0f172a;
}

.quota-page {
	background: #f1f5f9;
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, sans-serif;
}

.pagination-wrapper {
    display: flex;
    justify-content: center;
    align-items: center;
    margin-top: 20px;
    width: 100%;
}

.pagination-container {
    display: flex;
    align-items: center;
    gap: 12px;
}

.pg-info {
    min-width: 110px;
    text-align: center;
}

.set {
		font-size: 3.4rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1;
    margin-bottom: .6rem;
}

.admin-page-topbar {
  display: flex;
  align-items: center;
  gap: 14px;
  //margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid #e2e8f0;
}

.admin-back-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #ffffff;
  border: 1.5px solid #e2e8f0;
  cursor: pointer;
  color: #374151;
  flex-shrink: 0;
  transition: background 0.15s, border-color 0.15s;
}

.admin-back-btn:hover {
  background: #f1f5f9;
  border-color: #94a3b8;
}


body {
  font-family: Inter, sans-serif;
  background: #f8f9fb;
  padding: 20px;
}

.setup {
  font-weight: 600;
}

.quota-page {
  max-width: 1200px;
  margin: auto;
}

.header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.subtitle {
  margin-top: -10px;
  color: #6d6d6d;
  margin-bottom: 1rem;
}

.header-actions button {
  margin-left: 10px;
}

.btn-create {
  	display: inline-flex;
    align-items: center;
    gap: .5rem;
    padding: .8rem 1.6rem;
    background: #0f172a;
    border: none;
    border-radius: .8rem;
    font-size: 1.4rem;
    font-weight: 700;
    color: #ffffff;
    cursor: pointer;
    font-family: inherit;
    transition: background .15s;
}

.btn-secondary {
  background: white;
  padding: 10px 18px;
  border-radius: 8px;
  border: 1px solid #dcdcdc;
  cursor: pointer;
}

.filters-row {
  display: flex;
  gap: 3rem;
  margin: 20px 0;
  border: 2px solid #e7e7e7;
  border-radius: 1rem;
  height: 9rem;
  padding: 2rem;
  background: white;
}

.filter {
  padding: 2rem;
}

.option {
  width: 45rem;
  border-radius: 0.5rem;
  height: 3rem;
  font-weight: 600;
  background: #F3F3F5;
  border: none;
}

.filter label {
  display: block;
  font-size: 14px;
}

.labels {
  color: black;
  font-weight: 600;
  margin-right: 1rem;
}

.filter select {
  width: 200px;
  padding: 8px;
  border-radius: 8px;
  border: 1px solid #ccc;
}

.box {
    font-size: 1.3rem;
    font-weight: 600;
    color: #475569;
    margin-bottom: 1.2rem;
}

.stats-row {
  display: flex;
  gap: 20px;
  margin-bottom: 30px;
}

.stat-box {
  flex: 1;
  background: white;
  padding: 20px;
  border-radius: 12px;
  text-align: left;
  border: 1px solid #eee;
  color: black;
}

.stat-box h3 { 
    font-size: 3.4rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1;
    margin-bottom: .6rem;
}

.stat-box span {
  font-size: 1.3rem;
  color: #94a3b8;
}

.quota-cards {
  display: flex;
  gap: 20px;
}

.quota-card {
  background: white;
  padding: 20px;
  width: 32%;
  border-radius: 14px;
  border: 2px solid #e7e7e7;
}

.quota-card.selected {
  border-color: #5a8dfd;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.icon {
  width: 35px;
  height: 35px;
  background: #f2e5ff;
  border-radius: 8px;
}

.badge {
  background: #000;
  color: #fff;
  padding: 4px 10px;
  font-size: 12px;
  border-radius: 6px;
}

.amount {
  color: #00a854;
  font-size: 20px;
  font-weight: bold;
}

.dates p {
  margin: 3px 0;
  font-size: 14px;
}

.card-footer {
  margin-top: 15px;
  display: flex;
  justify-content: space-between;
}

.config {
  margin-top: 2rem;
  border-radius: 1rem;
}

.panel-heading {
  border: none;
  background: transparent;
}

.head {
  font-weight: 600;
}

.btn-outline {
  border: 1px solid #ccc;
  padding: 8px 14px;
  background: white;
  border-radius: 1rem;
  cursor: pointer;
}

/* ============================================================
   QUOTA SETUP WIDGET
   MOBILE RESPONSIVE OVERRIDES
   Existing HTML / classes / Angular / JS untouched
   ============================================================ */


/* ------------------------------------------------------------
   TABLET
   ------------------------------------------------------------ */
@media (max-width: 991px) {

  .quota-page {
    width: 100%;
    max-width: 100%;
    padding: 0 14px;
    box-sizing: border-box;
    overflow-x: hidden;
  }

  /* Header */
  .header-row {
    align-items: flex-start;
    gap: 14px;
  }

  .admin-page-topbar {
    min-width: 0;
  }

  .headd {
    font-size: 2.3rem;
  }

  .header-actions {
    flex-shrink: 0;
  }

  .btn-create {
    white-space: nowrap;
  }

  /* Stats */
  .stats-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
  }

  .stat-box {
    min-width: 0;
  }

  /* Approval table */
  #approvalFlowSection {
    width: 100%;
  }

  #approvalFlowSection .panel-body {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  #approvalFlowSection table {
    min-width: 650px;
  }
}


/* ------------------------------------------------------------
   MOBILE
   ------------------------------------------------------------ */
@media (max-width: 767px) {

  .quota-page {
    width: 100%;
    max-width: 100%;
    padding: 0 10px;
    margin: 0 auto;
    overflow-x: hidden;
  }


  /* ==========================================================
     HEADER
     ========================================================== */

  .header-row {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    width: 100%;
  }

  .admin-page-topbar {
    width: 100%;
    min-width: 0;
    padding-bottom: 10px;
  }

  .headd {
    font-size: 2.2rem;
    line-height: 1.2;
  }

  .header-actions {
    width: 100%;
    margin-left: 0;
  }

  .header-actions button {
    margin-left: 0;
  }

  .btn-create {
    width: 100%;
    justify-content: center;
    min-height: 42px;
    padding: 9px 14px;
    font-size: 13px;
  }

  .subtitle {
    margin-top: 0;
    margin-bottom: 18px;
    font-size: 12px;
    line-height: 1.5;
  }


  /* ==========================================================
     STATS
     ========================================================== */

  .stats-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    margin-bottom: 20px;
  }

  .stat-box {
    width: 100%;
    min-width: 0;
    padding: 15px;
    border-radius: 10px;
  }

  .stat-box .box {
    font-size: 11px;
    line-height: 1.35;
    margin-bottom: 9px;
  }

  .stat-box .set {
    font-size: 2.3rem;
    line-height: 1.1;
    margin-bottom: 6px;
    overflow-wrap: anywhere;
  }

  .stat-box span {
    display: block;
    font-size: 10px;
    line-height: 1.4;
  }


  /* ==========================================================
     QUOTA TABLE WIDGET
     ========================================================== */

  .quota-page > div > sp-widget,
  .quota-page sp-widget {
    display: block;
    width: 100%;
    max-width: 100%;
  }


  /* ==========================================================
     APPROVAL FLOW
     ========================================================== */

  #approvalFlowSection {
    width: 100%;
    margin-top: 18px;
    border-radius: 10px;
    overflow: hidden;
  }

  #approvalFlowSection .panel-heading {
    padding: 12px 14px;
  }

  #approvalFlowSection .panel-heading h4 {
    margin: 0;
    font-size: 14px;
  }

  #approvalFlowSection .panel-body {
    padding: 12px;
    overflow-x: auto;
    overflow-y: visible;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
  }

  #approvalFlowSection table {
    min-width: 620px;
    margin-bottom: 0;
  }

  #approvalFlowSection th,
  #approvalFlowSection td {
    white-space: nowrap;
    font-size: 11px;
    padding: 9px 10px;
    vertical-align: middle;
  }


  /* ==========================================================
     PAGINATION
     ========================================================== */

  .pagination-wrapper {
    margin-top: 16px;
    padding: 0;
  }

  .pagination-container {
    width: 100%;
    justify-content: center;
    gap: 8px;
  }

  .pagination-container .pg-btn {
    min-height: 36px;
    padding: 7px 11px;
    font-size: 11px;
  }

  .pg-info {
    min-width: 85px;
    font-size: 11px;
  }


  /* ==========================================================
     GENERAL TABLE SAFETY
     ========================================================== */

  .quota-page .table-responsive {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .quota-page table {
    max-width: none;
  }
}


/* ------------------------------------------------------------
   SMALL PHONES
   ------------------------------------------------------------ */
@media (max-width: 480px) {

  .quota-page {
    padding: 0 7px;
  }

  .headd {
    font-size: 2rem;
  }

  .subtitle {
    font-size: 11px;
  }


  /* Stats */
  .stats-row {
    gap: 8px;
  }

  .stat-box {
    padding: 12px;
    border-radius: 9px;
  }

  .stat-box .box {
    font-size: 10px;
  }

  .stat-box .set {
    font-size: 2rem;
  }

  .stat-box span {
    font-size: 9px;
  }


  /* Create button */
  .btn-create {
    min-height: 40px;
    font-size: 12px;
  }


  /* Approval section */
  #approvalFlowSection .panel-heading {
    padding: 11px 12px;
  }

  #approvalFlowSection .panel-body {
    padding: 10px;
  }

  #approvalFlowSection table {
    min-width: 570px;
  }

  #approvalFlowSection th,
  #approvalFlowSection td {
    font-size: 10px;
    padding: 8px;
  }


  /* Pagination */
  .pagination-container {
    gap: 5px;
  }

  .pagination-container .pg-btn {
    padding: 6px 9px;
    font-size: 10px;
  }

  .pg-info {
    min-width: 75px;
    font-size: 10px;
  }
}


/* ------------------------------------------------------------
   EXTRA SMALL PHONES
   ------------------------------------------------------------ */
@media (max-width: 360px) {

  .quota-page {
    padding: 0 5px;
  }

  .headd {
    font-size: 1.85rem;
  }

  .stats-row {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .stat-box {
    padding: 13px;
  }

  .stat-box .set {
    font-size: 2.1rem;
  }

  #approvalFlowSection table {
    min-width: 540px;
  }

  .pagination-container {
    gap: 4px;
  }

  .pagination-container .pg-btn {
    padding: 6px 8px;
  }
}


/* ------------------------------------------------------------
   MOBILE HORIZONTAL SCROLL SAFETY
   ------------------------------------------------------------ */

@media (max-width: 767px) {

  .quota-page,
  .header-row,
  .stats-row {
    box-sizing: border-box;
    max-width: 100%;
  }

  .quota-page input,
  .quota-page select,
  .quota-page textarea,
  .quota-page button {
    max-width: 100%;
  }

  /*
     Prevent long content from creating page-level
     horizontal scrolling.
  */
  .quota-page {
    overflow-x: hidden;
  }

  /*
     Tables can scroll independently when necessary.
  */
  #approvalFlowSection .panel-body {
    overscroll-behavior-x: contain;
  }
}

/* ============================================================
   STAT CARD NUMBER SIZING
   ============================================================ */

/* Desktop */
.stat-box .set {
  font-size: 2.8rem;
  line-height: 1.1;
  font-weight: 700;
}

/* Tablet */
@media (max-width: 991px) {
  .stat-box .set {
    font-size: 2.5rem;
  }
}

/* Mobile */
@media (max-width: 767px) {
  .stat-box .set {
    font-size: 1.9rem;
    line-height: 1.15;
  }
}

/* Small phones */
@media (max-width: 480px) {
  .stat-box .set {
    font-size: 1.7rem;
  }
}

/* Very small phones */
@media (max-width: 360px) {
  .stat-box .set {
    font-size: 1.8rem;
  }
}

sp_widget.script:
(function() {

	data.currencySymbol = gs.getProperty('x_ctans_incentnow.currency_symbol','$');
	data.currencyPosition = gs.getProperty('x_ctans_incentnow.currency_position','before');
  data.isEdit    = !!options.quota_batch_id;
  data.quotaModel = {};
	data.isTerritoryEnabled =
    new x_ctans_incentnow.IncentNowUtils().isTerritoryExtensionActive() === true;

	if (data.isTerritoryEnabled) {
	data.tableWidget=$sp.getWidget('incentnow-table-widget',{ table: 'x_ctans_incentnow_quota',view:'territory',viewperiod:'false'});
	}
	else
		{
			data.tableWidget=$sp.getWidget('incentnow-table-widget',{ table: 'x_ctans_incentnow_quota',view:'portal_view',viewperiod:'false'});
		}
	data.isIncentNowGroupAdmin= gs.hasRole('x_ctans_incentnow.business_group_admin') || gs.hasRole('x_ctans_incentnow.admin') || gs.hasRole('x_ctans_incentnow.territory_admin') ;


  /* ================= FISCAL CALENDAR ================= */

  data.fiscalPeriods = [];

  var periodGR = new GlideRecordSecure('x_ctans_incentnow_fiscal_calendar');
  periodGR.orderByDesc('fiscal_year_name');
  periodGR.setLimit(12);
  periodGR.query();

  while (periodGR.next()) {
    data.fiscalPeriods.push({
      id:        periodGR.getUniqueValue(),
      name:      periodGR.getValue('fiscal_year_name'),
      startDate: '',
      endDate:   ''
    });
  }

  /* ================= BUSINESS UNITS ================= */

  data.businessUnits = [];

  var buGR = new GlideRecordSecure('business_unit');
  buGR.orderBy('name');
  buGR.query();

  while (buGR.next()) {
    data.businessUnits.push({
      id:   buGR.getUniqueValue(),
      name: buGR.getValue('name')
    });
  }

  /* ================= USERS ================= */

  data.availableUsers = [];

	var userGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
	userGR.orderBy('user.name');
	userGR.query();

	while (userGR.next()) {
			data.availableUsers.push({
					id: userGR.getValue('user'),
					name: userGR.getDisplayValue('user') || '',
					email: userGR.user.email ? userGR.user.email.toString() : ''
			});
	}

  /* ================= CHECK EXISTING ================= */

 if (input && input.action === 'check_existing') {

    var countGR = new GlideAggregate('x_ctans_incentnow_user_quota_assignment');
    countGR.addQuery('quota.financial_year', input.period_id);
    countGR.addAggregate('COUNT');
    countGR.query();

    if (countGR.next()) {
        data.count = parseInt(countGR.getAggregate('COUNT'), 10);
    }
}

  /* ================= GET USER INFO ================= */

  if (input && input.action === 'get_user_info') {
    var uGR = new GlideRecordSecure('');
    if (uGR.get(input.user_id)) {
      var businessUnit   = '';
      var businessUnitId = '';
      if (uGR.getValue('business_unit')) {
        var bu = new GlideRecordSecure('business_unit');
        if (bu.get(uGR.getValue('business_unit'))) {
          businessUnit   = bu.getValue('name');
          businessUnitId = bu.getUniqueValue();
        }
      }
      data.userInfo = {
        name:           uGR.getValue('name'),
        email:          uGR.getValue('email'),
        businessUnit:   businessUnit,
        businessUnitId: businessUnitId
      };
    }
  }

  /* ================= GET BU USERS ================= */

  if (input && input.action === 'get_bu_users') {
    data.users = [];
    var buUserGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
    buUserGR.addQuery('business_unit', input.bu_id);
    buUserGR.query();

    while (buUserGR.next()) {
      var buName = '';
      if (buUserGR.getValue('business_unit')) {
        var b = new GlideRecordSecure('business_unit');
        if (b.get(buUserGR.getValue('business_unit'))) {
          buName = b.getValue('name');
        }
      }
      data.users.push({
        id:           buUserGR.getValue('user'),
        name:         buUserGR.user.name.toString(),
        email:        buUserGR.user.email.toString(),
        businessUnit: buName
      });
    }
  }

  /* ================= SAVE QUOTAS ================= */

  if (input && input.action === 'saveQuota') {
    var q       = input.quotaData;
    var quotaGR = new GlideRecordSecure('x_ctans_incentnow_quota');

    if (quotaGR.get(data.sys_id)) {

    } else {
      quotaGR.initialize();
    }

    quotaGR.name            = q.name;
    quotaGR.description     = q.notes;
    quotaGR.fiscal_year     = q.fiscalPeriodId;
    quotaGR.quota_frequency = q.frequency;
    quotaGR.quota_metric    = q.valueType;
    quotaGR.target_value    = q.quotaValue;

    var sysId = quotaGR.update() || quotaGR.insert();

    return {
      status: "success",
      sys_id: sysId
    };
  }

  /* ================= LOAD QUOTA ASSIGNMENTS ================= */

	data.activeQuotaCount = 0;

	var activeGR = new GlideAggregate('x_ctans_incentnow_quota');
	activeGR.addQuery('status', 'active');
	activeGR.addAggregate('COUNT');
	activeGR.query();

	if (activeGR.next()) {
			data.activeQuotaCount = parseInt(activeGR.getAggregate('COUNT'), 10);
	}

	data.assignedRepCount = 0;

	var repGA = new GlideAggregate('x_ctans_incentnow_user_quota_assignment');
	repGA.addEncodedQuery('quota.status!=inactive'); // adjust if your status field differs
	repGA.addAggregate('COUNT', 'user');             // change 'user' if your field name is different
	repGA.groupBy('user');
	repGA.query();

	data.assignedRepCount = 0;
		while (repGA.next()) {
				data.assignedRepCount++;
		}

  data.quotaAssignments = [];

  var quotaGR2 = new GlideRecordSecure('x_ctans_incentnow_quota');
  quotaGR2.orderByDesc('sys_created_on');
  quotaGR2.query();

  while (quotaGR2.next()) {
    var rawQ    = quotaGR2.getValue('target_value');
    var targetQ = (!rawQ || isNaN(parseFloat(rawQ))) ? 0 : parseFloat(rawQ);

		// Count assigned reps for this quota
    var repGA = new GlideAggregate('x_ctans_incentnow_user_quota_assignment');
    repGA.addQuery('quota', quotaGR2.getUniqueValue());   // <-- use the reference field to Quota
    repGA.addAggregate('COUNT', 'user');
    repGA.groupBy('user');
    repGA.query();

		var assignedRepCount = 0;
			while (repGA.next()) {
					assignedRepCount++;
			}

    data.quotaAssignments.push({
      id:                 quotaGR2.getUniqueValue(),
      name:               quotaGR2.getValue('name') || '',
			status: quotaGR2.getValue('status') || '',
      periodName:         quotaGR2.getDisplayValue('fiscal_year') || '',
      targetValue:        targetQ,
      targetDisplay:      targetQ.toString(),
      quotaMetric:        quotaGR2.getDisplayValue('quota_metric') || '',
      distributionMethod: quotaGR2.getDisplayValue('quota_frequency') || '',
			assignedReps: assignedRepCount
    });
  }

	//approval flow

		if (input && input.action == "getApprovalFlow") {

				data.approvalFlow = [];

				var apprGR = new GlideRecordSecure('sysapproval_approver');
				apprGR.addQuery('document_id', input.quotaId);
				apprGR.orderByDesc('sys_created_on');
				apprGR.query();

				while (apprGR.next()) {
						data.approvalFlow.push({
								approver: apprGR.getDisplayValue('approver'),
								state: apprGR.getDisplayValue('state'),
								updated: apprGR.getDisplayValue('sys_updated_on'),
								comments: apprGR.getDisplayValue('comments')
						});
				}
		}





})();
